        void ScriptA4Shizune::a4_shizune() {
            if (ks::globals::exit_scenario) return;
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A4_SHIZUNE);
            ks::SceneManager::set_script(SCRIPT_A4_SHIZUNE);
            ks::SceneManager::init_savedata(ks::progress);
            ks::SceneManager::set(ks::SceneManager("script_a4_shizune"));
        
            ScriptA4Shizune::a4_shizune_grand_strategy(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Shizune::a4_shizune_off_by_one(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Shizune::a4_shizune_invasion(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Shizune::a4_shizune_parfait(); // INLINE CALL
            ks::SceneManager::timeskip();
            if (ks::progress.refuse_misha) {
                ScriptA4Shizune::a4_shizune_the_summit(); // INLINE CALL
                ks::SceneManager::timeskip();
                ScriptA4Shizune::a4_shizune_succession(); // INLINE CALL
                ScriptA4Shizune::a4_shizune_sneaking_mission(); // INLINE CALL
                ks::SceneManager::timeskip();
                ScriptA4Shizune::a4_shizune_infinity(); // INLINE CALL
            } else {
                ScriptA4Shizune::a4_shizune_present_tense(); // INLINE CALL
                ks::SceneManager::timeskip();
                ScriptA4Shizune::a4_shizune_spiral(); // INLINE CALL
                ks::SceneManager::timeskip();
                ScriptA4Shizune::a4_shizune_terminal(); // INLINE CALL
            }
        }
